import os
import random
import struct
from typing import List

# Generator for QuickJS js_load_file fuzz: file data contents
# The harness will supply the filename, and the file at that path will contain
# the bytes we return here. js_load_file(ctx, &len, filename) reads raw bytes.
# Goal: produce valid, interesting file contents that exercise code paths:
# - Empty file
# - Small text (ASCII, UTF-8 with BOM, long line, many short lines)
# - Binary blobs with NULs
# - Various sizes around typical boundaries (1, 2, 3, 4, 8, 16, 64, 256, 1024, 2048, 4096)
# - JSON-looking data and JS-looking headers (though js_load_file just loads bytes)
# - Repeated patterns and randomized blocks
# - Different line endings (\n, \r\n)
# Limit: <= 4096 bytes

MAX_SIZE = 4096

_ascii_words = [
    b"hello", b"world", b"quickjs", b"fuzz", b"test", b"example", b"data",
    b"alpha", b"beta", b"gamma", b"delta", b"epsilon", b"zeta",
]

_json_snippets = [
    b"{}", b"[]", b"{\"a\":1}", b"{\"nested\":{\"x\":[1,2,3]}}",
    b"[true,false,null,123,\"str\"]",
]

_js_snippets = [
    b"// comment\n",
    b"/* block */\n",
    b"let x=1;\n",
    b"const buf=Array(10).fill(0);\n",
    b"function f(a){return a+1;}\n",
]

_bom_utf8 = b"\xEF\xBB\xBF"
_bom_utf16le = b"\xFF\xFE"
_bom_utf16be = b"\xFE\xFF"


def _rand(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _repeat_pattern(pattern: bytes, total: int) -> bytes:
    if not pattern:
        return b""
    reps, rem = divmod(total, len(pattern))
    return pattern * reps + pattern[:rem]


def _make_text_block(r: random.Random, target: int) -> bytes:
    lines: List[bytes] = []
    while sum(len(l) for l in lines) < target:
        choice = r.randrange(5)
        if choice == 0:
            lines.append(r.choice(_ascii_words) + b"\n")
        elif choice == 1:
            # long line
            ln = r.randint(20, 120)
            lines.append(_repeat_pattern(r.choice(_ascii_words) + b" ", ln) + b"\n")
        elif choice == 2:
            # CRLF
            lines.append(b";".join(r.choice(_ascii_words) for _ in range(r.randint(2,6))) + b"\r\n")
        elif choice == 3:
            # JS-ish
            lines.append(r.choice(_js_snippets))
        else:
            # JSON-ish line
            lines.append(r.choice(_json_snippets) + b"\n")
    blob = b"".join(lines)
    return blob[:target]


def _make_structured_blob(r: random.Random, target: int) -> bytes:
    # Combine header + payload patterns
    parts: List[bytes] = []
    # Optional BOM
    if r.random() < 0.3:
        parts.append(r.choice([_bom_utf8, _bom_utf16le, _bom_utf16be]))
    # Random selection of snippets
    for _ in range(r.randint(1, 5)):
        parts.append(r.choice(_js_snippets + _json_snippets))
    # Insert binary runs with zeros and high bytes
    if r.random() < 0.8:
        parts.append(b"\x00" * r.randint(1, 64))
    if r.random() < 0.8:
        parts.append(_repeat_pattern(b"\xFF\x00", r.randint(2, 128)))
    # Random block
    parts.append(_rand(r, r.randint(0, 128)))
    blob = b"".join(parts)
    if len(blob) >= target:
        return blob[:target]
    # pad with pattern
    pad = _repeat_pattern(b"AB\x00\xFF", target - len(blob))
    return blob + pad


def _size_choice(r: random.Random) -> int:
    # Choose interesting sizes with bias
    interesting = [0,1,2,3,4,7,8,15,16,31,32,63,64,127,128,255,256,511,512,1023,1024,1536,2048,3072,4095,4096]
    if r.random() < 0.7:
        return r.choice(interesting)
    return r.randint(0, MAX_SIZE)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    variant = r.randrange(8)
    size = _size_choice(r)

    if size == 0:
        return b""

    if variant == 0:
        # Pure random bytes
        return _rand(r, size)
    elif variant == 1:
        # ASCII/UTF text-like
        return _make_text_block(r, size)
    elif variant == 2:
        # Structured mix with BOM/snippets and binary
        return _make_structured_blob(r, size)
    elif variant == 3:
        # Repeated small pattern
        pat_len = r.choice([1,2,3,4,8,16,32])
        pattern = _rand(r, pat_len)
        return _repeat_pattern(pattern, size)
    elif variant == 4:
        # JSON-looking whole buffer (padded/truncated)
        base = r.choice(_json_snippets)
        # Optionally expand with nested arrays/objects
        extra = b""
        for _ in range(r.randint(0, 5)):
            extra += b"\n" + r.choice(_json_snippets)
        blob = base + extra
        if len(blob) < size:
            blob += _repeat_pattern(b" \n", size - len(blob))
        return blob[:size]
    elif variant == 5:
        # NUL-heavy with occasional ASCII
        out = bytearray()
        while len(out) < size:
            if r.random() < 0.6:
                out.extend(b"\x00" * r.randint(1, min(64, size - len(out))))
            else:
                w = r.choice(_ascii_words)
                out.extend(w + b"\n")
        return bytes(out[:size])
    elif variant == 6:
        # Size boundary emphasis: header + exact boundary padding
        header = b"QJS\x00" + struct.pack("<I", size)
        body = _rand(r, max(0, size - len(header)))
        return (header + body)[:size]
    else:
        # Mixed line endings and Unicode
        content = bytearray()
        while len(content) < size:
            pick = r.randrange(4)
            if pick == 0:
                content.extend(("line-" + str(r.randint(0, 1_000_000))).encode("utf-8") + b"\n")
            elif pick == 1:
                content.extend(("key" + str(r.randint(0,999)) + ": value").encode("utf-8") + b"\r\n")
            elif pick == 2:
                # some UTF-8 multi-byte chars
                u = ["π", "✓", "漢", "💡", "é", "ø"]
                s = (" ".join(r.choice(u) for _ in range(r.randint(1,4))) + "\n").encode("utf-8")
                content.extend(s)
            else:
                content.extend(_rand(r, r.randint(0, 32)))
        return bytes(content[:size])
